async function iniciar() {
  if (!process.env.DATABASE_URL) {
    throw new Error('Falta la variable de entorno DATABASE_URL');
  }

  const repositorio = conectarPostgres(process.env.DATABASE_URL);
  await repositorio.inicializar();

  // Migra una sola vez los links heredados; los codigos ya presentes nunca se pisan.
  for (const link of linksIniciales) {
    await repositorio.crear(link);
  }

  const app = crearApp(repositorio);
  const puerto = Number(process.env.PORT) || 3000;
  const server = app.listen(puerto, '0.0.0.0', function () {
    console.log(`Corta escuchando en el puerto ${puerto}`);
  });

  async function cerrar() {
    server.close(async function () {
      await repositorio.cerrar();
      process.exit(0);
    });
  }

  process.once('SIGTERM', cerrar);
  process.once('SIGINT', cerrar);

  return { app, server, repositorio };
}

test('GET /:codigo con codigo existente redirige (302) al destino e incrementa clicks', async function () {
  const ctx = await iniciarServerDeTest([
    { codigo: 'a3k', url: 'https://ejemplo.com/pagina-larga', clicks: 0, creado: '2026-03-02T14:11:09.000Z' }
  ]);

  try {
    const res = await fetch(ctx.baseUrl + '/a3k', { redirect: 'manual' });

    assert.equal(res.status, 302);
    assert.equal(res.headers.get('location'), 'https://ejemplo.com/pagina-larga');

    const links = ctx.leerDB();
    assert.equal(links.find(function (l) { return l.codigo === 'a3k'; }).clicks, 1);
  } finally {
    await ctx.cerrar();
  }
});

test('GET /:codigo con codigo inexistente responde 404 sin tocar clicks de otros links', async function () {
  const ctx = await iniciarServerDeTest([
    { codigo: 'a3k', url: 'https://ejemplo.com/pagina-larga', clicks: 5, creado: '2026-03-02T14:11:09.000Z' }
  ]);

  try {
    const res = await fetch(ctx.baseUrl + '/zzz', { redirect: 'manual' });

    assert.equal(res.status, 404);
    assert.equal(ctx.leerDB()[0].clicks, 5);
  } finally {
    await ctx.cerrar();
  }
});
